CREATE OR ALTER PROCEDURE dbo.usp_save_client_policy
  @client_id NVARCHAR(MAX), @display_name NVARCHAR(MAX),
  @payee_name NVARCHAR(MAX),
  @remit_address NVARCHAR(MAX),
  @agency_name NVARCHAR(MAX),
  @agency_phone NVARCHAR(MAX),
  @agency_hours NVARCHAR(MAX),
  @plan_terms NVARCHAR(MAX),
  @hardship_accepted BIT,
  @deceased_policy NVARCHAR(MAX),
  @extras NVARCHAR(MAX),
  @owner_name NVARCHAR(MAX), @change_ticket NVARCHAR(MAX)
AS
BEGIN
  SET NOCOUNT ON; SET XACT_ABORT ON;
  IF @client_id IS NULL OR LEN(LTRIM(RTRIM(@client_id))) = 0 OR LEN(@client_id) > 50
    OR @client_id LIKE '%[^a-zA-Z0-9_.-]%' COLLATE Latin1_General_100_BIN2
    THROW 51010, 'Use an ASCII record key with letters, digits, dot, underscore or hyphen.', 1;
  IF @owner_name IS NULL OR LEN(LTRIM(RTRIM(@owner_name))) = 0 OR DATALENGTH(@owner_name) > 256
    OR @change_ticket IS NULL OR LEN(LTRIM(RTRIM(@change_ticket))) = 0 OR DATALENGTH(@change_ticket) > 200
    THROW 51010, 'Owner and change ticket are required.', 1;
  IF @display_name IS NULL OR LEN(LTRIM(RTRIM(@display_name))) = 0 OR DATALENGTH(@display_name) > 400 THROW 51010, 'Invalid display_name.', 1;
  IF DATALENGTH(@payee_name) > 400 THROW 51010, 'Invalid payee_name.', 1;
  IF DATALENGTH(@remit_address) > 800 THROW 51010, 'Invalid remit_address.', 1;
  IF DATALENGTH(@agency_name) > 400 THROW 51010, 'Invalid agency_name.', 1;
  IF DATALENGTH(@agency_phone) > 60 THROW 51010, 'Invalid agency_phone.', 1;
  IF DATALENGTH(@agency_hours) > 400 THROW 51010, 'Invalid agency_hours.', 1;
  IF DATALENGTH(@plan_terms) > 32000 THROW 51010, 'Invalid plan_terms.', 1;
  IF DATALENGTH(@deceased_policy) > 800 THROW 51010, 'Invalid deceased_policy.', 1;
  IF @extras IS NULL OR LEN(LTRIM(RTRIM(@extras))) = 0 OR DATALENGTH(@extras) > 32000 THROW 51010, 'Invalid extras.', 1;
  IF (@plan_terms IS NOT NULL AND ISJSON(@plan_terms) <> 1) OR ISJSON(@extras) <> 1
      THROW 51010, 'Policy JSON is invalid.', 1;
  BEGIN TRY
    BEGIN TRANSACTION;
    IF EXISTS (SELECT 1 FROM dbo.client_policy WITH (UPDLOCK,HOLDLOCK) WHERE client_id=@client_id)
      UPDATE dbo.client_policy SET display_name=@display_name,payee_name=@payee_name,remit_address=@remit_address,agency_name=@agency_name,agency_phone=@agency_phone,agency_hours=@agency_hours,plan_terms=@plan_terms,hardship_accepted=@hardship_accepted,deceased_policy=@deceased_policy,extras=@extras,
        owner_name=@owner_name,change_ticket=@change_ticket,updated_by=ORIGINAL_LOGIN(),updated_at=SYSDATETIMEOFFSET(),
        review_status='draft',approved_by=NULL,approved_at=NULL WHERE client_id=@client_id;
    ELSE
      INSERT dbo.client_policy (client_id,display_name,payee_name,remit_address,agency_name,agency_phone,agency_hours,plan_terms,hardship_accepted,deceased_policy,extras,owner_name,change_ticket)
      VALUES (@client_id,@display_name,@payee_name,@remit_address,@agency_name,@agency_phone,@agency_hours,@plan_terms,@hardship_accepted,@deceased_policy,@extras,@owner_name,@change_ticket);
    COMMIT;
    SELECT client_id,review_status,row_version FROM dbo.client_policy WHERE client_id=@client_id;
  END TRY
  BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK;
    THROW;
  END CATCH
END;
GO

CREATE OR ALTER PROCEDURE dbo.usp_approve_client_policy
  @client_id VARCHAR(50), @expected_version BINARY(8), @approval_ticket NVARCHAR(MAX)
AS
BEGIN
  SET NOCOUNT ON; SET XACT_ABORT ON;
  IF @approval_ticket IS NULL OR LEN(LTRIM(RTRIM(@approval_ticket))) = 0 OR DATALENGTH(@approval_ticket)>200
    THROW 51011, 'An approval ticket is required.', 1;
  UPDATE dbo.client_policy SET review_status='approved',approved_by=ORIGINAL_LOGIN(),approved_at=SYSDATETIMEOFFSET(),change_ticket=@approval_ticket
    WHERE client_id=@client_id AND row_version=@expected_version AND review_status='draft'
      AND updated_by<>ORIGINAL_LOGIN() AND owner_name IS NOT NULL
      ;
  IF @@ROWCOUNT<>1 THROW 51011, 'Approval requires a different login, the reviewed row version and complete evidence.', 1;
END;
GO

CREATE OR ALTER TRIGGER dbo.tr_client_policy_audit ON dbo.client_policy AFTER INSERT, UPDATE, DELETE
AS
BEGIN
  SET NOCOUNT ON;
  INSERT dbo.configuration_audit (table_name,record_key,operation,actor_login,before_hash,after_hash,change_ticket)
  SELECT 'client_policy',COALESCE(i.client_id,d.client_id),
    CASE WHEN d.client_id IS NULL THEN 'INSERT' WHEN i.client_id IS NULL THEN 'DELETE' ELSE 'UPDATE' END,
    ORIGINAL_LOGIN(),
    CASE WHEN d.client_id IS NULL THEN NULL ELSE HASHBYTES('SHA2_256',(SELECT d.* FOR JSON PATH, WITHOUT_ARRAY_WRAPPER)) END,
    CASE WHEN i.client_id IS NULL THEN NULL ELSE HASHBYTES('SHA2_256',(SELECT i.* FOR JSON PATH, WITHOUT_ARRAY_WRAPPER)) END,
    COALESCE(i.change_ticket,d.change_ticket)
  FROM inserted i FULL JOIN deleted d ON i.client_id=d.client_id;
END;
GO

