CREATE OR ALTER PROCEDURE dbo.usp_save_control_evidence
  @control_id NVARCHAR(MAX), @framework NVARCHAR(MAX),
  @control_summary NVARCHAR(MAX),
  @implementation_state NVARCHAR(MAX),
  @evidence_url NVARCHAR(MAX),
  @owner_name NVARCHAR(MAX), @change_ticket NVARCHAR(MAX)
AS
BEGIN
  SET NOCOUNT ON; SET XACT_ABORT ON;
  IF @control_id IS NULL OR LEN(LTRIM(RTRIM(@control_id))) = 0 OR LEN(@control_id) > 80
    OR @control_id LIKE '%[^a-zA-Z0-9_.-]%' COLLATE Latin1_General_100_BIN2
    THROW 51010, 'Use an ASCII record key with letters, digits, dot, underscore or hyphen.', 1;
  IF @owner_name IS NULL OR LEN(LTRIM(RTRIM(@owner_name))) = 0 OR DATALENGTH(@owner_name) > 256
    OR @change_ticket IS NULL OR LEN(LTRIM(RTRIM(@change_ticket))) = 0 OR DATALENGTH(@change_ticket) > 200
    THROW 51010, 'Owner and change ticket are required.', 1;
  IF @framework IS NULL OR LEN(LTRIM(RTRIM(@framework))) = 0 OR DATALENGTH(@framework) > 40 THROW 51010, 'Invalid framework.', 1;
  IF @control_summary IS NULL OR LEN(LTRIM(RTRIM(@control_summary))) = 0 OR DATALENGTH(@control_summary) > 2000 THROW 51010, 'Invalid control_summary.', 1;
  IF @implementation_state IS NULL OR LEN(LTRIM(RTRIM(@implementation_state))) = 0 OR DATALENGTH(@implementation_state) > 40 THROW 51010, 'Invalid implementation_state.', 1;
  IF DATALENGTH(@evidence_url) > 4096 THROW 51010, 'Invalid evidence_url.', 1;
  IF @framework NOT IN ('SOC2','ISO27001','HITRUST','WCAG','ADA','SHARED')
      THROW 51010, 'Invalid framework.', 1;
    IF @implementation_state NOT IN ('planned','implemented','not_applicable')
      THROW 51010, 'Invalid implementation state.', 1;
    IF @evidence_url IS NOT NULL AND (@evidence_url NOT LIKE N'https://_%'
      OR @evidence_url LIKE N'%@%' OR @evidence_url LIKE N'%?%' OR @evidence_url LIKE N'%#%'
      OR @evidence_url LIKE N'% %' OR @evidence_url LIKE N'%'+NCHAR(9)+N'%'
      OR @evidence_url LIKE N'%'+NCHAR(10)+N'%' OR @evidence_url LIKE N'%'+NCHAR(13)+N'%')
      THROW 51010, 'Use an HTTPS evidence repository URL without credentials or access tokens.', 1;
  BEGIN TRY
    BEGIN TRANSACTION;
    IF EXISTS (SELECT 1 FROM dbo.control_evidence WITH (UPDLOCK,HOLDLOCK) WHERE control_id=@control_id)
      UPDATE dbo.control_evidence SET framework=@framework,control_summary=@control_summary,implementation_state=@implementation_state,evidence_url=@evidence_url,
        owner_name=@owner_name,change_ticket=@change_ticket,updated_by=ORIGINAL_LOGIN(),updated_at=SYSDATETIMEOFFSET(),
        review_status='draft',approved_by=NULL,approved_at=NULL WHERE control_id=@control_id;
    ELSE
      INSERT dbo.control_evidence (control_id,framework,control_summary,implementation_state,evidence_url,owner_name,change_ticket)
      VALUES (@control_id,@framework,@control_summary,@implementation_state,@evidence_url,@owner_name,@change_ticket);
    COMMIT;
    SELECT control_id,review_status,row_version FROM dbo.control_evidence WHERE control_id=@control_id;
  END TRY
  BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK;
    THROW;
  END CATCH
END;
GO

